      grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.AllowUserToDeleteRows=false;grid.AllowUserToResizeRows=false;grid.RowHeadersVisible=false;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.BackgroundColor=Color.White;grid.BorderStyle=BorderStyle.None;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.MultiSelect=false;grid.DefaultCellStyle.Font=new Font("Tahoma",12);grid.DefaultCellStyle.SelectionBackColor=Color.FromArgb(232,242,255);grid.DefaultCellStyle.SelectionForeColor=Color.Black;grid.ColumnHeadersDefaultCellStyle.Font=new Font("Tahoma",11,FontStyle.Bold);grid.ColumnHeadersHeight=48;grid.RowTemplate.Height=48;
      grid.Columns.Add("name","کالا");grid.Columns.Add("qty","تعداد");grid.Columns.Add("price","قیمت واحد");grid.Columns.Add("sum","جمع");
      var foot=new TableLayoutPanel{Dock=DockStyle.Bottom,Height=160,ColumnCount=3,RowCount=2,BackColor=Color.FromArgb(16,54,109),Padding=new Padding(20)};foot.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,33.33f));foot.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,33.33f));foot.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,33.34f));
      SetupMoneyLabel(total,"جمع کالاها");SetupMoneyLabel(discount,"تخفیف");SetupMoneyLabel(payable,"قابل پرداخت");foot.Controls.Add(total,2,0);foot.Controls.Add(discount,1,0);foot.Controls.Add(payable,0,0);foot.SetRowSpan(total,2);foot.SetRowSpan(discount,2);foot.SetRowSpan(payable,2);
