    void SetupMoneyLabel(Label l,string caption){l.Dock=DockStyle.Fill;l.TextAlign=ContentAlignment.MiddleCenter;l.Font=new Font("Tahoma",15,FontStyle.Bold);l.ForeColor=Color.White;l.Tag=caption;}
    public void UpdateSale(IList<SaleLine> lines,long disc){
      if(IsDisposed)return;if(InvokeRequired){BeginInvoke(new Action(()=>UpdateSale(lines,disc)));return;}
      grid.Rows.Clear();long sub=0;foreach(var x in lines){sub+=x.Total;grid.Rows.Add(x.Product.Name,x.Qty.ToString("N0"),x.Product.Price.ToString("N0")+" تومان",x.Total.ToString("N0")+" تومان");}
      long pay=Math.Max(0,sub-disc);total.Text="جمع کالاها\n"+sub.ToString("N0")+" تومان";discount.Text="تخفیف\n"+disc.ToString("N0")+" تومان";payable.Text="قابل پرداخت\n"+pay.ToString("N0")+" تومان";
      if(lines.Count>0){var x=lines[lines.Count-1];lastItem.Text="آخرین کالا:  "+x.Product.Name+"   |   "+x.Product.Price.ToString("N0")+" تومان";state.Text="اقلام خرید شما";}else{lastItem.Text="سبد خرید خالی است";state.Text="آماده ثبت خرید شما";}
    }
  }

  class ManualItemDialog:Form {
    readonly TextBox name=new TextBox(),barcode=new TextBox(),price=new TextBox(); public Product Result;
    public ManualItemDialog(string code="",string title="",long p=0){
      Text="ثبت دستی کالا";Width=520;Height=360;StartPosition=FormStartPosition.CenterParent;RightToLeft=RightToLeft.Yes;RightToLeftLayout=true;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;
      name.Text=title;barcode.Text=code;price.Text=p>0?p.ToString():"";
      AddField("نام کالا",name,35);AddField("بارکد / کد",barcode,115);AddField("قیمت (تومان)",price,195);
      var ok=new Button{Text="افزودن به فاکتور",Left=270,Top=270,Width=190,Height=42,BackColor=Color.FromArgb(22,105,220),ForeColor=Color.White,FlatStyle=FlatStyle.Flat};ok.FlatAppearance.BorderSize=0;
      ok.Click+=(s,e)=>{long v;if(string.IsNullOrWhiteSpace(name.Text)||!long.TryParse(Digits(price.Text),out v)||v<0){MessageBox.Show(this,"نام و قیمت معتبر را وارد کنید.","وب ساز");return;}Result=new Product{Name=name.Text.Trim(),Barcode=barcode.Text.Trim(),Price=v};DialogResult=DialogResult.OK;Close();};Controls.Add(ok);
    }
    void AddField(string label,TextBox box,int top){Controls.Add(new Label{Text=label,Left=325,Top=top,Width=135,Height=25,TextAlign=ContentAlignment.MiddleRight});box.Left=35;box.Top=top+28;box.Width=425;box.Height=30;Controls.Add(box);}
    static string Digits(string s){if(s==null)return "";var b=new StringBuilder();foreach(char c in s){if(c>='0'&&c<='9')b.Append(c);else if(c>='۰'&&c<='۹')b.Append((char)('0'+c-'۰'));else if(c>='٠'&&c<='٩')b.Append((char)('0'+c-'٠'));}return b.ToString();}
  }

  class DiscountDialog:Form {
    readonly TextBox amount=new TextBox();public long Amount;
    public DiscountDialog(long current){Text="تخفیف فاکتور";Width=460;Height=230;StartPosition=FormStartPosition.CenterParent;RightToLeft=RightToLeft.Yes;RightToLeftLayout=true;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;Controls.Add(new Label{Text="مبلغ تخفیف (تومان)",Left=245,Top=35,Width=170,Height=30,TextAlign=ContentAlignment.MiddleRight});amount.Left=35;amount.Top=70;amount.Width=380;amount.Text=current.ToString();Controls.Add(amount);var b=new Button{Text="اعمال تخفیف",Left=245,Top=125,Width=170,Height=42,BackColor=Color.FromArgb(22,105,220),ForeColor=Color.White,FlatStyle=FlatStyle.Flat};b.FlatAppearance.BorderSize=0;b.Click+=(s,e)=>{long v;if(!long.TryParse(Normalize(amount.Text),out v)||v<0){MessageBox.Show(this,"مبلغ معتبر وارد کنید.");return;}Amount=v;DialogResult=DialogResult.OK;Close();};Controls.Add(b);}
    static string Normalize(string s){var b=new StringBuilder();foreach(char c in s??""){if(c>='0'&&c<='9')b.Append(c);else if(c>='۰'&&c<='۹')b.Append((char)('0'+c-'۰'));else if(c>='٠'&&c<='٩')b.Append((char)('0'+c-'٠'));}return b.ToString();}
  }

  class SaleForm:Form {
    readonly MainForm owner; readonly List<Product> catalog; readonly CustomerDisplayForm customer; readonly List<SaleLine> lines=new List<SaleLine>(); readonly DataGridView grid=new DataGridView(); readonly TextBox scan=new TextBox(); readonly Label subtotal=new Label(),discountLabel=new Label(),payable=new Label(),screenState=new Label(); long discount;
    public SaleForm(MainForm o,List<Product> products,CustomerDisplayForm c){
      owner=o;catalog=products??new List<Product>();customer=c;Text="فروش جدید - وب ساز";WindowState=FormWindowState.Maximized;StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(242,247,255);RightToLeft=RightToLeft.Yes;RightToLeftLayout=true;KeyPreview=true;
      var head=new Panel{Dock=DockStyle.Top,Height=110,BackColor=Color.White,Padding=new Padding(22)};
      var title=new Label{Text="فروش جدید",Dock=DockStyle.Right,Width=180,Font=new Font("Tahoma",18,FontStyle.Bold),TextAlign=ContentAlignment.MiddleCenter,ForeColor=Color.FromArgb(20,64,126)};
      scan.Width=360;scan.Height=38;scan.Left=ClientSize.Width/2;scan.Font=new Font("Tahoma",14);scan.PlaceholderTextCompat("بارکد را اسکن یا وارد کنید و Enter بزنید");scan.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){e.SuppressKeyPress=true;AddByCode(scan.Text.Trim());scan.Clear();}};
      var add=new Button{Text="ثبت دستی کالا",Width=145,Height=42,Left=22,Top=32,FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(232,241,255),ForeColor=Color.FromArgb(20,86,190)};add.FlatAppearance.BorderSize=0;add.Click+=(s,e)=>AddManual("");
      screenState.Text=customer==null?"نمایشگر مشتری پیدا نشد":"نمایشگر مشتری متصل";screenState.AutoSize=true;screenState.Left=180;screenState.Top=43;screenState.ForeColor=customer==null?Color.DarkOrange:Color.SeaGreen;screenState.Font=new Font("Tahoma",9,FontStyle.Bold);
      head.Controls.Add(add);head.Controls.Add(screenState);head.Controls.Add(scan);head.Controls.Add(title);head.Resize+=(s,e)=>{scan.Left=Math.Max(360,(head.Width-scan.Width)/2);scan.Top=34;};
      grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AllowUserToAddRows=false;grid.RowHeadersVisible=false;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;grid.BackgroundColor=Color.White;grid.BorderStyle=BorderStyle.None;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.DefaultCellStyle.Font=new Font("Tahoma",11);grid.ColumnHeadersDefaultCellStyle.Font=new Font("Tahoma",10,FontStyle.Bold);grid.ColumnHeadersHeight=42;grid.RowTemplate.Height=42;grid.Columns.Add("name","کالا");grid.Columns.Add("barcode","بارکد");grid.Columns.Add("qty","تعداد");grid.Columns.Add("price","فی");grid.Columns.Add("sum","جمع");
      var tools=new FlowLayoutPanel{Dock=DockStyle.Right,Width=190,FlowDirection=FlowDirection.TopDown,Padding=new Padding(14),BackColor=Color.White};tools.Controls.Add(MakeButton("حذف ردیف",()=>RemoveSelected(),Color.FromArgb(255,239,239),Color.Firebrick));tools.Controls.Add(MakeButton("تخفیف",()=>SetDiscount(),Color.FromArgb(255,248,224),Color.DarkGoldenrod));tools.Controls.Add(MakeButton("فاکتور جدید",()=>NewSale(),Color.FromArgb(232,245,255),Color.FromArgb(22,105,220)));
      var foot=new Panel{Dock=DockStyle.Bottom,Height=115,BackColor=Color.FromArgb(16,54,109)};SetupTotal(subtotal,700,"جمع");SetupTotal(discountLabel,390,"تخفیف");SetupTotal(payable,40,"قابل پرداخت");foot.Controls.Add(subtotal);foot.Controls.Add(discountLabel);foot.Controls.Add(payable);foot.Resize+=(s,e)=>{payable.Left=25;discountLabel.Left=Math.Max(270,foot.Width/3);subtotal.Left=Math.Max(520,foot.Width*2/3-150);};
      Controls.Add(grid);Controls.Add(tools);Controls.Add(foot);Controls.Add(head);Shown+=(s,e)=>{scan.Focus();RefreshSale();};FormClosed+=(s,e)=>{if(customer!=null)customer.UpdateSale(new List<SaleLine>(),0);};
    }
    Button MakeButton(string text,Action a,Color back,Color fore){var b=new Button{Text=text,Width=150,Height=48,Margin=new Padding(5,10,5,0),BackColor=back,ForeColor=fore,FlatStyle=FlatStyle.Flat};b.FlatAppearance.BorderSize=0;b.Click+=(s,e)=>a();return b;}
    void SetupTotal(Label l,int left,string caption){l.Left=left;l.Top=18;l.Width=280;l.Height=78;l.ForeColor=Color.White;l.TextAlign=ContentAlignment.MiddleCenter;l.Font=new Font("Tahoma",13,FontStyle.Bold);l.Tag=caption;}
    void AddByCode(string code){if(string.IsNullOrWhiteSpace(code))return;var p=catalog.FirstOrDefault(x=>string.Equals(x.Barcode,code,StringComparison.OrdinalIgnoreCase));if(p==null){AddManual(code);return;}AddProduct(p);}
    void AddManual(string code){using(var d=new ManualItemDialog(code)){if(d.ShowDialog(this)==DialogResult.OK&&d.Result!=null){catalog.Add(d.Result);owner.SaveManualProduct(d.Result);AddProduct(d.Result);}}scan.Focus();}
    void AddProduct(Product p){var l=lines.FirstOrDefault(x=>x.Product.Barcode!=""&&p.Barcode!=""&&x.Product.Barcode==p.Barcode);if(l!=null)l.Qty++;else lines.Add(new SaleLine{Product=p,Qty=1});RefreshSale();}
    void RemoveSelected(){if(grid.SelectedRows.Count==0)return;int i=grid.SelectedRows[0].Index;if(i>=0&&i<lines.Count)lines.RemoveAt(i);RefreshSale();scan.Focus();}
    void SetDiscount(){using(var d=new DiscountDialog(discount)){if(d.ShowDialog(this)==DialogResult.OK){discount=d.Amount;RefreshSale();}}scan.Focus();}
    void NewSale(){if(lines.Count>0&&MessageBox.Show(this,"فاکتور فعلی پاک شود و فروش جدید شروع شود؟","وب ساز",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;lines.Clear();discount=0;RefreshSale();scan.Focus();}
    void RefreshSale(){grid.Rows.Clear();long sub=0;foreach(var x in lines){sub+=x.Total;grid.Rows.Add(x.Product.Name,x.Product.Barcode,x.Qty.ToString("N0"),x.Product.Price.ToString("N0"),x.Total.ToString("N0"));}long pay=Math.Max(0,sub-discount);subtotal.Text="جمع\n"+sub.ToString("N0")+" تومان";discountLabel.Text="تخفیف\n"+discount.ToString("N0")+" تومان";payable.Text="قابل پرداخت\n"+pay.ToString("N0")+" تومان";if(customer!=null)customer.UpdateSale(lines.ToList(),discount);}
  }

  static class TextBoxCompat { public static void PlaceholderTextCompat(this TextBox t,string text){t.Tag=text;t.ForeColor=Color.Gray;t.Text=text;t.GotFocus+=(s,e)=>{if(t.ForeColor==Color.Gray){t.Text="";t.ForeColor=Color.Black;}};t.LostFocus+=(s,e)=>{if(string.IsNullOrWhiteSpace(t.Text)){t.Text=text;t.ForeColor=Color.Gray;}};} }

  class MainForm:Form {
    const int BW=1492,BH=1054; Image bg; string root; int syncing; readonly object dataLock=new object(); readonly List<UiHotspot> hot=new List<UiHotspot>(); UiHotspot hover,pressed; CustomerDisplayForm customerDisplay;
    string DataFile=>Path.Combine(root,"records.sync"); string Ini=>Path.Combine(root,"settings.txt"); string DeviceFile=>Path.Combine(root,"device.id");
    public MainForm(){
      root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"WebsazStore");Directory.CreateDirectory(root);Text="وب ساز - مدیریت ساده فروشگاه";StartPosition=FormStartPosition.CenterScreen;WindowState=FormWindowState.Maximized;DoubleBuffered=true;RightToLeft=RightToLeft.Yes;Icon=SystemIcons.Application;SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.UserPaint,true);
      bg=LoadOverlayImage();BuildHotspots();Paint+=DrawUI;Resize+=(s,e)=>Invalidate();MouseMove+=MoveUI;MouseLeave+=(s,e)=>{hover=null;Cursor=Cursors.Default;Invalidate();};MouseDown+=DownUI;MouseUp+=UpUI;
      var tm=new System.Windows.Forms.Timer();tm.Interval=60000;tm.Tick+=(s,e)=>ThreadPool.QueueUserWorkItem(_=>SyncCore(false));tm.Start();
      Shown+=(s,e)=>{EnsureCustomerDisplay();ThreadPool.QueueUserWorkItem(_=>{Thread.Sleep(8000);SyncCore(false);});};
    }
    void BuildHotspots(){
      hot.Add(new UiHotspot("انتقال همه اطلاعات",new Rectangle(895,430,265,52),()=>StartMigration()));hot.Add(new UiHotspot("بررسی قبل از انتقال",new Rectangle(615,430,260,52),()=>CheckData()));
      hot.Add(new UiHotspot("مهاجرت",new Rectangle(1210,210,235,58),()=>StartMigration()));hot.Add(new UiHotspot("فروش",new Rectangle(1210,270,235,58),()=>OpenSale()));hot.Add(new UiHotspot("اتصال سایت",new Rectangle(1210,625,235,58),()=>SiteDialog()));hot.Add(new UiHotspot("تنظیمات",new Rectangle(1210,685,235,58),()=>System.Diagnostics.Process.Start("explorer.exe",root)));
      hot.Add(new UiHotspot("وبسایت",new Rectangle(985,655,175,110),()=>SiteDialog()));
      hot.Add(new UiHotspot("فروش جدید",new Rectangle(980,850,180,135),()=>OpenSale()));
      hot.Add(new UiHotspot("کالاها",new Rectangle(800,850,170,135),()=>MessageBox.Show(this,"کالاها از اطلاعات همگام‌شده و مهاجرت‌شده خوانده می‌شوند.","وب ساز")));
      hot.Add(new UiHotspot("موجودی",new Rectangle(620,850,170,135),()=>MessageBox.Show(this,"موجودی در همگام‌سازی بعدی با اطلاعات فروشگاه مچ می‌شود.","وب ساز")));
      hot.Add(new UiHotspot("خرید و ورود کالا",new Rectangle(435,850,175,135),()=>MessageBox.Show(this,"ورود کالا از طریق مهاجرت یا ثبت دستی در فروش انجام می‌شود.","وب ساز")));
      hot.Add(new UiHotspot("حساب‌ها",new Rectangle(255,850,175,135),()=>MessageBox.Show(this,"حساب‌ها پس از مهاجرت در اطلاعات محلی نگهداری می‌شوند.","وب ساز")));
      hot.Add(new UiHotspot("گزارش‌ها",new Rectangle(70,850,175,135),()=>MessageBox.Show(this,"گزارش‌های فروش پس از ثبت عملیات فروش فعال می‌شوند.","وب ساز")));
    }
    Image LoadOverlayImage(){try{var exe=Application.ExecutablePath;using(var f=File.OpenRead(exe)){if(f.Length<16)return null;f.Seek(-16,SeekOrigin.End);var m=new byte[8];f.Read(m,0,8);var lenb=new byte[8];f.Read(lenb,0,8);if(Encoding.ASCII.GetString(m)!="WSUIJPG1")return null;long len=BitConverter.ToInt64(lenb,0);if(len<=0||len>f.Length)return null;f.Seek(-16-len,SeekOrigin.End);var b=new byte[len];f.Read(b,0,b.Length);using(var ms=new MemoryStream(b))return new Bitmap(ms);}}catch{return null;}}
    Rectangle UiRect(){double s=Math.Min((double)ClientSize.Width/BW,(double)ClientSize.Height/BH);int w=(int)(BW*s),h=(int)(BH*s);return new Rectangle((ClientSize.Width-w)/2,(ClientSize.Height-h)/2,w,h);}
    Point ToUi(Point p){var r=UiRect();double s=(double)r.Width/BW;return new Point((int)((p.X-r.X)/s),(int)((p.Y-r.Y)/s));}
    Rectangle FromUi(Rectangle x){var r=UiRect();double s=(double)r.Width/BW;return new Rectangle(r.X+(int)(x.X*s),r.Y+(int)(x.Y*s),(int)(x.Width*s),(int)(x.Height*s));}
    UiHotspot FindHot(Point p){var u=ToUi(p);return hot.FirstOrDefault(x=>x.R.Contains(u));}
    GraphicsPath Round(Rectangle r,int radius){var p=new GraphicsPath();int d=radius*2;p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
    void DrawUI(object s,PaintEventArgs e){e.Graphics.Clear(Color.FromArgb(239,246,255));if(bg!=null)e.Graphics.DrawImage(bg,UiRect());e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;if(hover!=null){var r=FromUi(hover.R);if(pressed==hover)r.Offset(0,2);using(var sh=Round(new Rectangle(r.X+3,r.Y+5,r.Width,r.Height),12))using(var b=new SolidBrush(Color.FromArgb(28,16,64,120)))e.Graphics.FillPath(b,sh);using(var p=Round(r,12))using(var b=new SolidBrush(Color.FromArgb(pressed==hover?52:24,21,105,220)))using(var pen=new Pen(Color.FromArgb(pressed==hover?230:175,21,105,220),pressed==hover?3:2)){e.Graphics.FillPath(b,p);e.Graphics.DrawPath(pen,p);}}
    }
    void MoveUI(object s,MouseEventArgs e){var h=FindHot(e.Location);if(h!=hover){hover=h;Cursor=h==null?Cursors.Default:Cursors.Hand;Invalidate();}}
    void DownUI(object s,MouseEventArgs e){if(e.Button!=MouseButtons.Left)return;pressed=FindHot(e.Location);Invalidate();}
    void UpUI(object s,MouseEventArgs e){var p=pressed;pressed=null;Invalidate();if(p!=null&&p==FindHot(e.Location)&&p.Click!=null)p.Click();}
    void EnsureCustomerDisplay(){if(customerDisplay!=null&&!customerDisplay.IsDisposed)return;var seller=Screen.FromControl(this);var target=Screen.AllScreens.FirstOrDefault(x=>x.DeviceName!=seller.DeviceName);if(target==null)return;customerDisplay=new CustomerDisplayForm(target);customerDisplay.Show();customerDisplay.Bounds=target.Bounds;}
    void OpenSale(){EnsureCustomerDisplay();RunBusy("در حال آماده‌سازی فروش و بارگذاری کالاها...",()=>{var products=LoadProducts();BeginInvoke(new Action(()=>{var f=new SaleForm(this,products,customerDisplay);f.Show(this);}));return "";},false);}
    void CheckData(){RunBusy("در حال بررسی اطلاعات و فایل‌های همگام‌سازی...",()=>"بررسی انجام شد.\nرکوردهای فعلی: "+Load().Count.ToString("N0")+"\nرکورد تکراری بر اساس کلید تطبیق ساخته نمی‌شود.",true);}
    void RunBusy(string text,Func<string> work,bool showMessage){var b=new BusyForm(text);Enabled=false;b.Show(this);ThreadPool.QueueUserWorkItem(_=>{string msg="";try{msg=work();}catch(Exception ex){msg="عملیات انجام نشد.\n"+ex.Message;}try{BeginInvoke(new Action(()=>{Enabled=true;b.Close();Activate();if(showMessage&&!string.IsNullOrEmpty(msg))MessageBox.Show(this,msg,"وب ساز");}));}catch{}});}
    string Device(){if(File.Exists(DeviceFile))return File.ReadAllText(DeviceFile).Trim();var x=Guid.NewGuid().ToString("N");File.WriteAllText(DeviceFile,x);return x;}
    Dictionary<string,string> Settings(){var d=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);if(File.Exists(Ini))foreach(var l in File.ReadAllLines(Ini)){int i=l.IndexOf('=');if(i>0)d[l.Substring(0,i)]=l.Substring(i+1);}return d;}
    void SaveSettings(string url,string key,string store){File.WriteAllLines(Ini,new[]{"url="+url,"key="+key,"store="+store});}
    string B64(string s)=>Convert.ToBase64String(Encoding.UTF8.GetBytes(s??"")); string UB64(string s){try{return Encoding.UTF8.GetString(Convert.FromBase64String(s));}catch{return "";}}
    string Hash(string s){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(s))).Replace("-","").ToLowerInvariant();}
    List<Rec> Load(){lock(dataLock){var a=new List<Rec>();if(!File.Exists(DataFile))return a;foreach(var l in File.ReadLines(DataFile)){var p=l.Split(new[]{'\t'},5);if(p.Length<5)continue;long u;long.TryParse(p[2],out u);a.Add(new Rec{T=UB64(p[0]),K=UB64(p[1]),U=u,H=UB64(p[3]),P=p[4]});}return a;}}
    void Merge(IEnumerable<Rec> inc){lock(dataLock){var m=Load().ToDictionary(x=>x.T+"|"+x.K,x=>x,StringComparer.OrdinalIgnoreCase);foreach(var r in inc){var k=r.T+"|"+r.K;Rec old;if(!m.TryGetValue(k,out old)||(r.U>old.U&&r.H!=old.H))m[k]=r;}using(var w=new StreamWriter(DataFile,false,new UTF8Encoding(false)))foreach(var r in m.Values)w.WriteLine(B64(r.T)+"\t"+B64(r.K)+"\t"+r.U+"\t"+B64(r.H)+"\t"+r.P);}}
    string Norm(object x){var s=(x??"").ToString().Trim().ToLowerInvariant();return new string(s.Where(c=>char.IsLetterOrDigit(c)||c>127).ToArray());}
    string J(object x){return (x??"").ToString().Replace("\\","\\\\").Replace("\"","\\\"").Replace("\r"," ").Replace("\n"," ");}
    string Pick(DataColumnCollection c,params string[] names){foreach(DataColumn x in c)foreach(var n in names)if(x.ColumnName.IndexOf(n,StringComparison.OrdinalIgnoreCase)>=0)return x.ColumnName;return "";}
    bool Any(string s,params string[] q){return q.Any(x=>s.IndexOf(x,StringComparison.OrdinalIgnoreCase)>=0);}
    void ImportTable(SqlConnection c,string schema,string table,List<Rec> all,ref int tables,ref int rows){string t=table.ToLowerInvariant(),type=null;if(Any(t,"kala","item","product","goods","کالا"))type="product";else if(Any(t,"customer","moshtari","person","party","client","مشتری"))type="customer";else if(Any(t,"factor","invoice","sale","forosh","فاکتور","فروش"))type="invoice";else if(Any(t,"anbar","stock","inventory","warehouse","انبار"))type="stock";else if(Any(t,"hesab","account","ledger","حساب"))type="account";if(type==null)return;var dt=new DataTable();try{new SqlDataAdapter("SELECT TOP 50000 * FROM ["+schema.Replace("]","]] ")+"] .["+table.Replace("]","]] ")+"]",c).Fill(dt);}catch{return;}if(dt.Rows.Count==0)return;string barcode=Pick(dt.Columns,"barcode","bar_code","ean","gtin","upc","بارکد"),code=Pick(dt.Columns,"u_code1","kalacode","itemcode","code","id","کد"),name=Pick(dt.Columns,"kalaname","itemname","productname","name","title","نام"),phone=Pick(dt.Columns,"mobile","phone","tel","موبایل","تلفن"),no=Pick(dt.Columns,"factorno","invoiceno","number","no","شماره"),date=Pick(dt.Columns,"date","tarikh","تاریخ"),total=Pick(dt.Columns,"total","mablagh","amount","جمع","مبلغ");int n=0;foreach(DataRow r in dt.Rows){var sb=new StringBuilder("{");for(int i=0;i<dt.Columns.Count;i++){if(i>0)sb.Append(',');sb.Append('"').Append(J(dt.Columns[i].ColumnName)).Append("\":\"").Append(J(r[i])).Append('"');}sb.Append('}');string key;if(type=="product")key=!string.IsNullOrEmpty(barcode)?"barcode:"+Norm(r[barcode]):!string.IsNullOrEmpty(code)?"code:"+Norm(r[code]):"name:"+Norm(string.IsNullOrEmpty(name)?"":r[name]);else if(type=="customer")key=!string.IsNullOrEmpty(phone)?"phone:"+Norm(r[phone]):!string.IsNullOrEmpty(code)?"code:"+Norm(r[code]):"name:"+Norm(string.IsNullOrEmpty(name)?"":r[name]);else if(type=="invoice")key="invoice:"+Norm(string.IsNullOrEmpty(no)?"":r[no])+":"+Norm(string.IsNullOrEmpty(date)?"":r[date])+":"+Norm(string.IsNullOrEmpty(total)?"":r[total]);else key=!string.IsNullOrEmpty(code)?"code:"+Norm(r[code]):"row:"+Norm(table)+":"+n;if(key.Length<5)key="row:"+Norm(table)+":"+n;string payload=sb.ToString();all.Add(new Rec{T=type,K=key,U=DateTimeOffset.UtcNow.ToUnixTimeSeconds(),H=Hash(payload),P=B64(payload)});n++;}if(n>0){tables++;rows+=n;}}
    IEnumerable<string> Servers(){var s=new HashSet<string>(StringComparer.OrdinalIgnoreCase){"localhost",@".\SQLEXPRESS"};foreach(var path in new[]{@"SOFTWARE\Microsoft\Microsoft SQL Server\Instance Names\SQL",@"SOFTWARE\WOW6432Node\Microsoft\Microsoft SQL Server\Instance Names\SQL"})try{using(var k=Registry.LocalMachine.OpenSubKey(path))if(k!=null)foreach(var n in k.GetValueNames())s.Add(n.Equals("MSSQLSERVER",StringComparison.OrdinalIgnoreCase)?"localhost":@".\"+n);}catch{}return s;}
    void StartMigration(){RunBusy("در حال شناسایی دیتابیس‌ها و انتقال اطلاعات...",()=>MigrateCore(),true);}
    string MigrateCore(){int dbs=0,tables=0,rows=0;var all=new List<Rec>();foreach(var server in Servers())try{using(var master=new SqlConnection("Data Source="+server+";Initial Catalog=master;Integrated Security=True;Connect Timeout=2;TrustServerCertificate=True")){master.Open();var names=new List<string>();using(var q=new SqlCommand("SELECT name FROM sys.databases WHERE database_id>4 AND state=0",master))using(var rd=q.ExecuteReader())while(rd.Read())names.Add(rd.GetString(0));foreach(var db in names)try{using(var c=new SqlConnection("Data Source="+server+";Initial Catalog="+db+";Integrated Security=True;Connect Timeout=3;TrustServerCertificate=True")){c.Open();dbs++;using(var q=new SqlCommand("SELECT TABLE_SCHEMA,TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_TYPE='BASE TABLE'",c))using(var rd=q.ExecuteReader()){var ts=new List<string[]>();while(rd.Read())ts.Add(new[]{rd.GetString(0),rd.GetString(1)});rd.Close();foreach(var z in ts)ImportTable(c,z[0],z[1],all,ref tables,ref rows);}}}catch{}}}catch{}Merge(all);return dbs==0?"دیتابیس قابل دسترس با ورود ویندوز پیدا نشد. هیچ نام کاربری یا رمزی درخواست نمی‌شود.":"مهاجرت انجام شد.\nدیتابیس‌ها: "+dbs+"\nجدول‌های شناسایی‌شده: "+tables+"\nرکوردهای مچ/واردشده: "+rows+"\n\nموارد تکراری ادغام می‌شوند.";}
    void SiteDialog(){var s=Settings();var f=new Form{Text="اتصال به سایت",Width=600,Height=430,StartPosition=FormStartPosition.CenterParent,RightToLeft=RightToLeft.Yes,RightToLeftLayout=true};var u=new TextBox{Left=40,Top=90,Width=500,Text=s.ContainsKey("url")?s["url"]:""};var k=new TextBox{Left=40,Top=175,Width=500,UseSystemPasswordChar=true,Text=s.ContainsKey("key")?s["key"]:""};var st=new TextBox{Left=40,Top=260,Width=500,Text=s.ContainsKey("store")?s["store"]:"default"};f.Controls.AddRange(new Control[]{new Label{Text="آدرس سایت",Left=390,Top=60,Width=150,TextAlign=ContentAlignment.MiddleRight},u,new Label{Text="کد اتصال",Left=390,Top=145,Width=150,TextAlign=ContentAlignment.MiddleRight},k,new Label{Text="شناسه فروشگاه",Left=360,Top=230,Width=180,TextAlign=ContentAlignment.MiddleRight},st});var b=new Button{Text="ذخیره و همگام‌سازی",Left=310,Top=320,Width=230,Height=45,BackColor=Color.FromArgb(22,105,220),ForeColor=Color.White,FlatStyle=FlatStyle.Flat};b.FlatAppearance.BorderSize=0;b.MouseEnter+=(x,y)=>b.BackColor=Color.FromArgb(10,84,190);b.MouseLeave+=(x,y)=>b.BackColor=Color.FromArgb(22,105,220);b.MouseDown+=(x,y)=>b.BackColor=Color.FromArgb(7,66,150);b.MouseUp+=(x,y)=>b.BackColor=Color.FromArgb(10,84,190);b.Click+=(x,y)=>{SaveSettings(u.Text.Trim(),k.Text.Trim(),st.Text.Trim());var busy=new BusyForm("در حال اتصال و همگام‌سازی اطلاعات...");b.Enabled=false;busy.Show(f);ThreadPool.QueueUserWorkItem(_=>{var msg=SyncCore(true);try{f.BeginInvoke(new Action(()=>{busy.Close();b.Enabled=true;MessageBox.Show(f,msg,"وب ساز");}));}catch{}});};f.Controls.Add(b);f.ShowDialog(this);}
    string Endpoint(string u){u=(u??"").Trim().TrimEnd('/');return u.EndsWith(".php",StringComparison.OrdinalIgnoreCase)?u:u+"/websaz-sync.php";}
    string Body(){var a=Load();var s=Settings();var sb=new StringBuilder("WEBSAZSYNC1\n").Append(B64(Device())).Append('\n').Append(B64(s.ContainsKey("store")?s["store"]:"default")).Append('\n').Append(a.Count).Append('\n');foreach(var r in a)sb.Append(B64(r.T)).Append('\t').Append(B64(r.K)).Append('\t').Append(r.U).Append('\t').Append(B64(r.H)).Append('\t').Append(r.P).Append('\n');return sb.ToString();}
    List<Rec> Parse(string x){var a=new List<Rec>();var l=x.Replace("\r","").Split('\n');if(l.Length<4||l[0]!="WEBSAZSYNC1")return a;for(int i=4;i<l.Length;i++){var p=l[i].Split(new[]{'\t'},5);if(p.Length<5)continue;long u;long.TryParse(p[2],out u);a.Add(new Rec{T=UB64(p[0]),K=UB64(p[1]),U=u,H=UB64(p[3]),P=p[4]});}return a;}
    string SyncCore(bool userVisible){if(Interlocked.CompareExchange(ref syncing,1,0)!=0)return "همگام‌سازی در حال انجام است.";try{var s=Settings();if(!s.ContainsKey("url")||!s.ContainsKey("key")||s["url"]==""||s["key"]=="")return "ابتدا آدرس سایت و کد اتصال را وارد کنید.";var req=(HttpWebRequest)WebRequest.Create(Endpoint(s["url"]));req.Method="POST";req.ContentType="application/octet-stream";req.Headers[HttpRequestHeader.Authorization]="Bearer "+s["key"];req.Timeout=30000;req.ReadWriteTimeout=30000;var b=Encoding.UTF8.GetBytes(Body());req.ContentLength=b.Length;using(var q=req.GetRequestStream())q.Write(b,0,b.Length);using(var resp=(HttpWebResponse)req.GetResponse())using(var rd=new StreamReader(resp.GetResponseStream()))Merge(Parse(rd.ReadToEnd()));File.WriteAllText(Path.Combine(root,"last_sync.txt"),DateTime.Now.ToString("s"));return "اطلاعات همه سیستم‌ها با سایت مچ شد.";}catch(Exception ex){return "اتصال سایت انجام نشد.\n"+ex.Message;}finally{Interlocked.Exchange(ref syncing,0);}}
    Dictionary<string,string> JsonPairs(string json){var d=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(Match m in Regex.Matches(json??"","\\\"(?<k>(?:\\\\.|[^\\\"])*)\\\"\\s*:\\s*\\\"(?<v>(?:\\\\.|[^\\\"])*)\\\"")){var k=Unesc(m.Groups["k"].Value);var v=Unesc(m.Groups["v"].Value);d[k]=v;}return d;}
    string Unesc(string s){return (s??"").Replace("\\\"","\"").Replace("\\\\","\\").Replace("\\n"," ").Replace("\\r"," ");}
    string FindValue(Dictionary<string,string> d,params string[] names){foreach(var n in names){var x=d.FirstOrDefault(kv=>kv.Key.IndexOf(n,StringComparison.OrdinalIgnoreCase)>=0);if(!string.IsNullOrEmpty(x.Key)&&!string.IsNullOrWhiteSpace(x.Value))return x.Value;}return "";}
    long ParseMoney(string s){var b=new StringBuilder();foreach(char c in s??""){if(c>='0'&&c<='9')b.Append(c);else if(c>='۰'&&c<='۹')b.Append((char)('0'+c-'۰'));else if(c>='٠'&&c<='٩')b.Append((char)('0'+c-'٠'));}long x;return long.TryParse(b.ToString(),out x)?x:0;}
    List<Product> LoadProducts(){var list=new List<Product>();foreach(var r in Load().Where(x=>string.Equals(x.T,"product",StringComparison.OrdinalIgnoreCase))){string json=UB64(r.P);var d=JsonPairs(json);string barcode=FindValue(d,"barcode","bar_code","ean","gtin","upc","بارکد");if(string.IsNullOrWhiteSpace(barcode)&&r.K.StartsWith("barcode:",StringComparison.OrdinalIgnoreCase))barcode=r.K.Substring(8);string name=FindValue(d,"kalaname","itemname","productname","name","title","نام","شرح");if(string.IsNullOrWhiteSpace(name))name=barcode!=""?"کالا "+barcode:"کالای بدون نام";string price=FindValue(d,"price","sellprice","saleprice","ghimat","fi","قیمت","فی");list.Add(new Product{Name=name.Trim(),Barcode=barcode.Trim(),Price=ParseMoney(price)});}return list.GroupBy(x=>(x.Barcode!=""?"b:"+x.Barcode:"n:"+x.Name),StringComparer.OrdinalIgnoreCase).Select(g=>g.First()).ToList();}
    public void SaveManualProduct(Product p){if(p==null)return;string payload="{\"barcode\":\""+J(p.Barcode)+"\",\"name\":\""+J(p.Name)+"\",\"price\":\""+p.Price+"\"}";string key=!string.IsNullOrWhiteSpace(p.Barcode)?"barcode:"+Norm(p.Barcode):"name:"+Norm(p.Name);Merge(new[]{new Rec{T="product",K=key,U=DateTimeOffset.UtcNow.ToUnixTimeSeconds(),H=Hash(payload),P=B64(payload)}});}
  }
  static class Program{[STAThread]static void Main(){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new MainForm());}}
